def letter_grade(score):
    if score >= 90:
        return "A"
    elif score >= 80:
        return "B"
    elif score >= 70:
        return "C"
    else:
        return "Review"

students = [("Linus", 92), ("Maya", 84), ("Sam", 67), ("Nora", 95)]

for rank, (name, score) in enumerate(students, start=1):
    grade = letter_grade(score)
    print(f"{rank}. {name:<6} | score={score} -> {grade}")

